          "oneLiner": "AI 抹平软件功能与工程差距并制造严重供给过剩后，真正决定胜负的是上游 Token 供应链与下游品牌信任，而从业者的机会只有「为 Agent 打工（活数据/物理接口/基础软件）」和「用 Agent 交付服务」两条路。",
